# Cabecera CSP + SRI alineada con PCI DSS v4.0 Req. 6.4.3 (control de scripts en checkout)
Content-Security-Policy: default-src 'self'; script-src 'self' https://js.psp.example 'sha256-...'; object-src 'none'; report-to csp-endpoint;
<script src="https://js.psp.example/v3/checkout.js" integrity="sha384-..." crossorigin="anonymous"></script>

Purpose limitation.ejemplo:
# Validación de limitación de finalidad en un gateway de datos (Rego / OPA)
default allow = false
allow {
  input.dataset.allowed_purposes[_] == input.request.declared_purpose
  input.subject.consent[input.request.declared_purpose] == true
}
